import user from '@/assets/imgs/user.png';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import { Employee } from '@/types/employee.types';

export default function EmployeeInfo() {
    const [employee, setEmployee] = useState<Employee | null>(null);
    const [loading, setLoading] = useState(false);

    const employeeId = useMemo(() => {
        try {
            const raw = localStorage.getItem('hr:lastAllowanceEmployeeId') || '';
            const n = Number(raw);
            return Number.isFinite(n) && n > 0 ? String(n) : '';
        } catch {
            return '';
        }
    }, []);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            if (!employeeId) {
                setEmployee(null);
                return;
            }
            setLoading(true);
            try {
                const res = await apiGet<{ data: Employee }>({ endpoint: endpoints.employee.show + employeeId });
                if (!cancelled) setEmployee(res.data.data);
            } catch {
                if (!cancelled) setEmployee(null);
            } finally {
                if (!cancelled) setLoading(false);
            }
        };
        load();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    return (
        <div className="flex flex-row items-start w-full mt-6 ">
            <div className="flex-2">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    اسم الموظف
                </p>
                <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    <img src={user} alt="" className="rounded-full w-10 h-10 object-cover" />
                    <div className="flex flex-col gap-1 text-nowrap">
                        <p className="tracking-normal text-primery-blue-900 font-medium text-sm">
                            {loading ? 'جاري التحميل…' : employee?.name || 'اختر موظف من نافذة إضافة بدل'}
                        </p>
                        <p className="tracking-normal text-white-blue-800 font-normal text-sm">
                            {employee ? `${employee.position} - ${employee.department}` : '—'}
                        </p>
                    </div>
                </div>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    كود الموظف
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {employee?.id ?? '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    قسم الموظف
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {employee?.department || '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    المسمى الوظيفي
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {employee?.position || '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    تاريخ التعين
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">
                    {employee?.created_at || '—'}
                </p>
            </div>
            <div className="flex-1">
                <p className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal bg-white-blue-100">
                    اجمالي الرواتب
                </p>
                <p className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] p-4">—</p>
            </div>
        </div>
    );
}
