import { ColumnDef, Row } from '@tanstack/react-table';
import TrashIcon from '@/components/icons/TrashIcon';
import { AllowanceRow } from '../../types/allowance.types';
import { apiDelete } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';

type AllowanceRowTable = AllowanceRow & { refreshTable?: () => void };

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<AllowanceRowTable> }) => {
    const refresh = row.original.refreshTable;
    return (
        <div className="cursor-pointer flex justify-center">
            <button
                type="button"
                className="bg-transparent border-0 p-0"
                onClick={async () => {
                    try {
                        await apiDelete({ endpoint: endpoints.allowance.delete + row.original.id });
                        toast.success('تم الحذف');
                        refresh?.();
                    } catch {
                        toast.error('تعذر الحذف');
                    }
                }}
            >
                <TrashIcon className="text-[#E81E1E]" />
            </button>
        </div>
    );
};

export const columns: ColumnDef<AllowanceRowTable>[] = [
    {
        id: 'employee_name',
        header: () => (
            <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الموظف
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-900 leading-[26.24px] font-medium tracking-normal">
                {row.original.employee_name || row.original.employee?.name || '—'}
            </div>
        ),
    },
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم البند
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.name}
            </div>
        ),
    },
    {
        accessorKey: 'note',
        header: () => {
            return (
                <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    وصف
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.note || '—'}
            </div>
        ),
    },
    {
        accessorKey: 'amount',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    المبلغ
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.amount}
                </div>
            );
        },
    },
    {
        accessorKey: 'date',
        header: () => {
            return (
                <div className="text-sm text-nowrap px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    التاريخ
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.date}
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-nowrap text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
